/* ── Preview ───────────────────────────────────────────────────────── */

function Preview({ paciente }: { paciente?: boolean }) {
  const [v, setV] = useState(!!paciente)
  return <PanelPreview borrador={aBorrador(extraccion)} vistaPaciente={v} onVistaPaciente={setV} />
}

